-- Тема 1: Общие положения (термины и определения) — топик id=1, категория id=1
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(1,1,'Что из перечисленного относится к термину "главная дорога"?',
'["Дорога с любым покрытием по отношению к грунтовой","Дорога, обозначенная знаками приоритета, по отношению к пересекаемой","Дорога с большим количеством полос","Дорога с освещением в тёмное время суток"]'::jsonb,1,
'Главная дорога — дорога, обозначенная знаками 2.1, 2.3.1–2.3.7 или 2.4 по отношению к пересекаемой, либо дорога с твёрдым покрытием по отношению к грунтовой, либо любая дорога по отношению к выездам с прилегающих территорий.',1),
(1,1,'Что означает термин "недостаточная видимость"?',
'["Видимость дороги менее 300 м в туман, дождь, снегопад или сумерки","Видимость менее 50 м в любое время суток","Отсутствие уличного освещения","Видимость менее 10 м"]'::jsonb,0,
'Недостаточная видимость — видимость дороги менее 300 м в условиях тумана, дождя, снегопада и т.п., а также в сумерки.',2),
(1,1,'Что понимается под термином "обгон"?',
'["Опережение одного или нескольких ТС, связанное с выездом на полосу встречного движения","Любое опережение попутного транспортного средства","Движение с превышением скорости","Опережение ТС в пределах своей полосы"]'::jsonb,0,
'Обгон — опережение одного или нескольких ТС, связанное с выездом на полосу (сторону проезжей части), предназначенную для встречного движения, и последующим возвратом на ранее занимаемую полосу.',3),
(1,1,'Что такое "остановка" транспортного средства согласно ПДД?',
'["Преднамеренное прекращение движения на срок более 5 минут","Преднамеренное прекращение движения ТС на время до 5 минут, а также большее, если это необходимо для посадки/высадки пассажиров или разгрузки","Прекращение движения из-за неисправности","Любая парковка транспортного средства"]'::jsonb,1,
'Остановка — преднамеренное прекращение движения ТС на время до 5 минут, а также на большее время, если это необходимо для посадки или высадки пассажиров либо загрузки или разгрузки транспортного средства.',4),
(1,1,'Что означает термин "уступить дорогу" (не создавать помех)?',
'["Полностью остановиться перед любым перекрёстком","Требование, означающее, что участник не должен начинать, возобновлять или продолжать движение, если это может вынудить других участников изменить направление или скорость","Пропустить только пешеходов","Снизить скорость до минимальной"]'::jsonb,1,
'Уступить дорогу — требование, означающее, что участник движения не должен начинать, возобновлять или продолжать движение, а также осуществлять маневр, если это может вынудить других участников движения, имеющих преимущество, изменить направление движения или скорость.',5),
(1,1,'Что такое "вынужденная остановка"?',
'["Прекращение движения из-за неисправности ТС, груза, состояния водителя или опасности, создаваемой грузом, состоянием дороги","Остановка по требованию сотрудника ГИБДД","Остановка для отдыха водителя","Остановка на светофоре"]'::jsonb,0,
'Вынужденная остановка — прекращение движения ТС из-за его технической неисправности или опасности, создаваемой перевозимым грузом, состоянием водителя (пассажира) или появлением препятствия на дороге.',6),
(1,1,'Что понимается под термином "препятствие"?',
'["Неподвижный объект на полосе движения, не позволяющий продолжить движение по этой полосе","Любое ограничение скорости","Дорожный знак","Пешеходный переход"]'::jsonb,0,
'Препятствие — неподвижный объект на полосе движения (неисправное ТС, дефект покрытия и т.п.), не позволяющий продолжать движение по этой полосе.',7),
(1,1,'Что означает термин "перекрёсток"?',
'["Место пересечения, примыкания или разветвления дорог на одном уровне","Любое место с дорожными знаками","Участок дороги с разметкой","Место остановки маршрутного транспорта"]'::jsonb,0,
'Перекрёсток — место пересечения, примыкания или разветвления дорог на одном уровне, ограниченное воображаемыми линиями соединения противоположных, наиболее удалённых от центра перекрёстка начал закруглений проезжих частей.',8),
(1,1,'Что такое "разделительная полоса"?',
'["Элемент дороги, разделяющий смежные проезжие части и не предназначенный для движения и остановки ТС","Обочина дороги","Полоса для велосипедистов","Крайняя правая полоса"]'::jsonb,0,
'Разделительная полоса — элемент дороги, разделяющий смежные проезжие части и не предназначенный для движения, остановки и стоянки транспортных средств.',9),
(1,1,'Что означает термин "организованная транспортная колонна"?',
'["Группа из трёх и более ТС с включёнными фарами, следующих в одном ряду друг за другом с сопровождением автомобиля ГИБДД","Любая группа автомобилей на дороге","Колонна грузовых автомобилей","Группа автомобилей на парковке"]'::jsonb,0,
'Организованная транспортная колонна — группа из трёх и более механических ТС с включёнными фарами, следующих в одном ряду друг за другом на минимально безопасном расстоянии за ведущим ТС с постоянно включённым проблесковым маячком синего и красного цвета.',10),
(1,1,'Что понимается под "уступить дорогу" в отношении пешехода?',
'["Пропустить пешехода, не изменяя скорость и направление","Не начинать и не продолжать движение, если это вынудит пешехода изменить направление или скорость","Остановиться перед любым пешеходом","Подать звуковой сигнал"]'::jsonb,1,
'Требование "уступить дорогу" означает, что водитель не должен начинать, возобновлять движение или осуществлять манёвр, если это вынудит пешехода, имеющего преимущество, изменить направление движения или скорость.',11),
(1,1,'Что такое "полоса движения"?',
'["Любая из продольных полос проезжей части, обозначенная или не обозначенная разметкой и имеющая ширину, достаточную для движения ТС в один ряд","Обочина дороги","Тротуар","Разделительная полоса"]'::jsonb,0,
'Полоса движения — любая из продольных полос проезжей части, обозначенная или не обозначенная разметкой и имеющая ширину, достаточную для движения автомобилей в один ряд.',12);
